function fuellUDP(lang){
	entities = model.getEntitySet().toArray();
//	ent = entities.getByName('Agent');
//	log("Entitäten="+entities.length);
	for (i=0;i<entities.length;i++) { //
		ent = entities[i];
		doProperty(lang,"_ENTI_NAME",ent,ent.getName())
		doProperty(lang,"_ENTI_COMMENT",ent,ent.getComment())
		doProperty(lang,"_ENTI_SYNONYM",ent,ent.getSynonym())

		attrs = ent.getAttributes().toArray();
		//log("Attrs="+attrs.length)
		for (j=0;j<attrs.length;j++) { //
			attr = attrs[j];
			//log(attr.getName(),attr.getComment());
			doProperty(lang,"_ATTR_NAME",attr,attr.getName());
			doProperty(lang,"_ATTR_COMMENT",attr,attr.getComment());			
		}		
		ent.setDirty(true);
	}
	relationships = model.getRelationSet().toArray();
	for (r=0;r<relationships.length;r++) { //
		rel = relationships[r];
		doProperty(lang,"_RELA_TEXT_FROM",rel,rel.getNameOnSource())
		doProperty(lang,"_RELA_TEXT_TO",rel,rel.getNameOnTarget())
		rel.setDirty(true);
	}
}

function liesUDP(lang){
	entities = model.getEntitySet().toArray();
	for (i=0;i<entities.length;i++) { //
		ent = entities[i];
		ent.setName(ent.getProperty(lang+"_ENTI_NAME"));
		ent.setComment(ent.getProperty(lang+"_ENTI_COMMENT"));
		ent.setSynonym(ent.getProperty(lang+"_ENTI_SYNONYM"));

		attrs = ent.getAttributes().toArray();
		//log("Attrs="+attrs.length)
		for (j=0;j<attrs.length;j++) { //
			attr = attrs[j];
			//log(attr.getName(),attr.getComment());
			attr.setName(attr.getProperty(lang+"_ATTR_NAME"));
			attr.setComment(attr.getProperty(lang+"_ATTR_COMMENT"));			
		}		
		ent.setDirty(true);
	}
	relationships = model.getRelationSet().toArray();
	for (r=0;r<relationships.length;r++) { 
		rel = relationships[r];
		if (rel.getName()=='Relation_42'){
		//	log(lang+"textfrom="+rel.getProperty(lang+"_RELA_TEXT_FROM"));
			rel.setComment("from="+rel.getProperty(lang+"_RELA_TEXT_FROM")
			+"\nto="+rel.getProperty(lang+"_RELA_TEXT_TO"))
		}
		rel.setNameOnSource(rel.getProperty(lang+"_RELA_TEXT_FROM"));
		rel.setNameOnTarget(rel.getProperty(lang+"_RELA_TEXT_TO"));
		rel.setDirty(true);
	}
}

